import { execFileSync } from "node:child_process";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const contract = JSON.parse(
  await readFile(path.join(root, "contracts/supplier-fulfilment.json"), "utf8"),
);
const models = emitModels(contract.models);
await writeGenerated(
  root,
  "backend/pkg/supplierfulfilment/types_generated.go",
  '// Code generated by scripts/generate-supplier-fulfilment.mjs; DO NOT EDIT.\npackage supplierfulfilment\nimport("time";"github.com/google/uuid";"github.com/tesserix/helivanta/pkg/supplierorder")\n' +
    models.go.replaceAll("SupplierOrderProduct", "supplierorder.SupplierOrderProduct") +
    `\nconst maximumLeaseSeconds=${contract.maximum_lease_seconds}\nconst maximumUnits=${contract.maximum_units}\n`,
  "packages/api/src/supplier-fulfilment-contract.ts",
  '// Code generated by scripts/generate-supplier-fulfilment.mjs; DO NOT EDIT.\nimport{z}from"zod";\nimport{SupplierOrderProductContract}from"./supplier-orders-contract";\n' +
    models.ts,
  "Supplier fulfilment",
);

const template = await readFile(
  path.join(root, "contracts/supplier-stock-schema.sql.tmpl"),
  "utf8",
);
for (const owner of ["supply", "pharmacy"]) {
  const stockRead =
    owner === "pharmacy"
      ? "pharmacy_outlet_allowed(tenant_id,location_id,false) OR pharmacy_stock_overview_allowed(tenant_id,location_id)"
      : "supply_stock_scope(tenant_id,organization_id,location_id,'read') OR supply_operating_owned(tenant_id,organization_id,location_id,ARRAY['administrator','inventory','warehouse','auditor','regulator'])";
  const body =
    "-- Generated by scripts/generate-supplier-fulfilment.mjs; DO NOT EDIT.\n" +
    template.replaceAll("{{owner}}", owner).replaceAll("{{stock_read}}", stockRead);
  const target = path.join(root, `backend/internal/modules/${owner}/supplier_fulfilment.sql`);
  if (process.argv.includes("--check")) {
    if ((await readFile(target, "utf8").catch(() => "")) !== body)
      throw new Error(`${owner} supplier schema drift`);
  } else {
    await writeFile(target, body);
  }
}

const orders = JSON.parse(
  await readFile(path.join(root, "contracts/supplier-orders.json"), "utf8"),
);
for (const owner of ["supply", "pharmacy"]) {
  const wireModels = {};
  if (owner === "pharmacy") wireModels.SupplierOrderProduct = orders.models.SupplierOrderProduct;
  wireModels.SupplierDispatchRecordedData = contract.models.Shipment;
  if (owner === "supply") wireModels.SupplierShipmentExchangeData = contract.models.Shipment;
  wireModels.ReceivingSummary = contract.models.ReceivingSummary;
  wireModels[
    owner === "supply" ? "SupplierReceivingExchangeData" : "SupplierReceivingRecordedData"
  ] = [
    { name: "shipment_id", type: "uuid" },
    { name: "source_tenant_id", type: "uuid" },
    { name: "summary", type: "ReceivingSummary" },
  ];
  const body = execFileSync("gofmt", [], {
    encoding: "utf8",
    input:
      '// Code generated by scripts/generate-supplier-fulfilment.mjs; DO NOT EDIT.\npackage contract\nimport("time";"github.com/google/uuid")\n' +
      emitModels(wireModels).go,
  });
  const target = path.join(
    root,
    `backend/internal/modules/${owner}/contract/fulfilment_types_generated.go`,
  );
  if (process.argv.includes("--check")) {
    if ((await readFile(target, "utf8")) !== body)
      throw new Error(`${owner} fulfilment wire drift`);
  } else await writeFile(target, body);
}
